const css = "\n    :root {\n      --teal: #035772; --sage: #AACBA8; --bg: #F6F9F5;\n      --text: #091405; --white: #fff; --teal-light: #e8f4f8;\n      --border: #dde8dd;\n    }\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Space Grotesk', sans-serif; background: var(--bg); color: var(--text); line-height: 1.7; font-size: 16px; }\n\n    .hero { background: linear-gradient(135deg, #022d3d 0%, var(--teal) 100%); color: white; padding: 72px 24px 56px; text-align: center; }\n    .hero-badge { display: inline-block; background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.3); border-radius: 20px; padding: 6px 16px; font-size: 0.78rem; letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 20px; }\n    .hero h1 { font-size: clamp(2rem, 5vw, 3rem); font-weight: 700; line-height: 1.2; max-width: 700px; margin: 0 auto 16px; }\n    .hero p { font-size: 1.05rem; opacity: 0.88; max-width: 560px; margin: 0 auto 32px; }\n    .hero-cta { display: inline-block; background: var(--sage); color: var(--teal); font-weight: 700; padding: 14px 32px; border-radius: 8px; text-decoration: none; transition: opacity 0.2s; }\n    .hero-cta:hover { opacity: 0.85; }\n\n    .quick-facts { background: var(--white); border-bottom: 1px solid var(--border); padding: 28px 24px; }\n    .quick-facts-inner { max-width: 900px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 24px; text-align: center; }\n    .fact-item strong { display: block; font-size: 1.5rem; font-weight: 700; color: var(--teal); }\n    .fact-item span { font-size: 0.78rem; color: #5a6e5a; text-transform: uppercase; letter-spacing: 0.05em; }\n\n    .main { max-width: 900px; margin: 56px auto; padding: 0 24px; }\n    .section-label { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.12em; color: var(--teal); font-weight: 600; margin-bottom: 8px; }\n    .section-title { font-size: clamp(1.4rem, 3vw, 2rem); font-weight: 700; margin-bottom: 16px; }\n    .section-lead { font-size: 0.97rem; color: #3d5240; max-width: 680px; margin-bottom: 32px; }\n\n    /* ANATOMY + INTRO GRID */\n    .intro-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: start; margin-bottom: 56px; }\n    .intro-text p { font-size: 0.95rem; color: #3d5240; margin-bottom: 14px; }\n    .highlight-box { border-left: 4px solid var(--teal); background: var(--teal-light); padding: 16px 20px; border-radius: 0 8px 8px 0; margin-top: 16px; }\n    .highlight-box p { color: var(--teal); font-weight: 600; font-size: 0.9rem; margin: 0; }\n\n    .anatomy-svg { background: var(--white); border: 1px solid var(--border); border-radius: 16px; padding: 24px; text-align: center; }\n    .anatomy-svg h3 { font-size: 0.88rem; font-weight: 700; color: var(--text); margin-bottom: 16px; }\n\n    /* DECISION SECTION */\n    .decision-section { background: var(--white); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); padding: 56px 24px; margin-bottom: 56px; }\n    .decision-inner { max-width: 900px; margin: 0 auto; }\n    .decision-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 32px; }\n    .decision-card { border-radius: 12px; padding: 28px; border: 1px solid; }\n    .decision-card h3 { font-size: 1rem; font-weight: 700; margin-bottom: 12px; }\n    .decision-card ul { list-style: none; padding: 0; }\n    .decision-card li { padding: 6px 0 6px 20px; position: relative; font-size: 0.88rem; }\n    .decision-card li::before { position: absolute; left: 0; font-weight: 700; }\n    .card-conservative { background: #f0f8f0; border-color: #6aaa6a; }\n    .card-conservative h3 { color: #1a5a1a; }\n    .card-conservative li::before { content: '✓'; color: #1a7a1a; }\n    .card-conservative li { color: #1a4a1a; }\n    .card-surgical { background: #e8f4f8; border-color: var(--teal); }\n    .card-surgical h3 { color: var(--teal); }\n    .card-surgical li::before { content: '→'; color: var(--teal); }\n    .card-surgical li { color: #0a3a5a; }\n    .decision-note { margin-top: 24px; padding: 20px 24px; background: #fff8e0; border: 1px solid #f0c040; border-radius: 10px; font-size: 0.88rem; color: #5a3800; }\n\n    /* GRAFT SECTION */\n    .graft-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; margin-top: 32px; }\n    .graft-card { background: var(--white); border: 1px solid var(--border); border-radius: 12px; padding: 20px; }\n    .graft-card .icon { font-size: 1.5rem; margin-bottom: 10px; }\n    .graft-card h4 { font-size: 0.9rem; font-weight: 700; color: var(--text); margin-bottom: 6px; }\n    .graft-card p { font-size: 0.8rem; color: #4a5e4a; line-height: 1.5; }\n    .graft-tag { display: inline-block; margin-top: 8px; padding: 3px 10px; border-radius: 20px; font-size: 0.7rem; font-weight: 600; }\n    .tag-preferred { background: #e0f5e0; color: #1a5a1a; }\n    .tag-alt { background: var(--teal-light); color: var(--teal); }\n    .tag-revision { background: #fff0e0; color: #8a4000; }\n\n    /* SANTI PROTOCOL */\n    .santi-box { background: var(--teal); color: white; border-radius: 16px; padding: 40px 48px; margin: 56px 0; }\n    .santi-box .section-label { color: var(--sage); }\n    .santi-box h2 { color: white; font-size: 1.5rem; font-weight: 700; margin-bottom: 12px; }\n    .santi-box p { color: rgba(255,255,255,0.85); font-size: 0.95rem; margin-bottom: 20px; }\n    .santi-steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 24px; }\n    .santi-step { background: rgba(255,255,255,0.1); border-radius: 10px; padding: 20px; }\n    .santi-step .num { font-size: 1.6rem; font-weight: 700; color: var(--sage); line-height: 1; margin-bottom: 8px; }\n    .santi-step h4 { font-size: 0.88rem; font-weight: 700; color: white; margin-bottom: 6px; }\n    .santi-step p { font-size: 0.8rem; color: rgba(255,255,255,0.8); margin: 0; }\n\n    /* RECOVERY TIMELINE */\n    .timeline-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 12px; margin-top: 32px; }\n    .tl-card { background: var(--white); border: 1px solid var(--border); border-radius: 10px; padding: 16px; text-align: center; }\n    .tl-card .timing { font-size: 1.1rem; font-weight: 700; color: var(--teal); margin-bottom: 4px; }\n    .tl-card .milestone { font-size: 0.78rem; color: #4a5e4a; line-height: 1.4; }\n\n    /* FAQ */\n    .faq-section { max-width: 900px; margin: 56px auto; padding: 0 24px; }\n    .faq-item { border-bottom: 1px solid var(--border); }\n    .faq-q { width: 100%; background: none; border: none; text-align: left; padding: 18px 4px; font-size: 0.95rem; font-weight: 600; color: var(--text); font-family: inherit; cursor: pointer; display: flex; justify-content: space-between; align-items: center; gap: 12px; }\n    .faq-q .arrow { color: var(--teal); font-size: 1.1rem; transition: transform 0.2s; }\n    .faq-a { display: none; padding: 0 4px 18px; font-size: 0.9rem; color: #3d5240; line-height: 1.7; }\n    .faq-item.open .faq-a { display: block; }\n    .faq-item.open .arrow { transform: rotate(180deg); }\n\n    /* PHYSICIAN */\n    .physician-strip { background: var(--teal-light); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); padding: 40px 24px; }\n    .physician-inner { max-width: 900px; margin: 0 auto; display: flex; gap: 28px; align-items: center; }\n    .physician-avatar { width: 80px; height: 80px; border-radius: 50%; background: var(--teal); display: flex; align-items: center; justify-content: center; color: white; font-size: 1.6rem; font-weight: 700; flex-shrink: 0; }\n    .physician-info h4 { font-size: 1rem; font-weight: 700; color: var(--teal); }\n    .physician-info p { font-size: 0.88rem; color: #4a5e4a; margin-top: 4px; }\n    .credentials { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }\n    .cred-tag { background: white; border: 1px solid var(--border); border-radius: 20px; padding: 4px 12px; font-size: 0.72rem; font-weight: 600; color: var(--teal); }\n\n    /* CTA */\n    .cta-section { background: var(--white); padding: 56px 24px; text-align: center; }\n    .cta-section h2 { font-size: 1.6rem; font-weight: 700; color: var(--text); margin-bottom: 12px; }\n    .cta-section p { color: #4a5e4a; max-width: 480px; margin: 0 auto 28px; }\n    .btn-primary { display: inline-block; background: var(--teal); color: white; padding: 14px 36px; border-radius: 8px; text-decoration: none; font-weight: 700; margin-right: 12px; margin-bottom: 12px; transition: opacity 0.2s; }\n    .btn-primary:hover { opacity: 0.85; }\n    .btn-secondary { display: inline-block; border: 2px solid var(--teal); color: var(--teal); padding: 12px 28px; border-radius: 8px; text-decoration: none; font-weight: 600; margin-bottom: 12px; transition: all 0.2s; }\n    .btn-secondary:hover { background: var(--teal); color: white; }\n\n    @media (max-width: 640px) {\n      .intro-grid, .decision-grid, .santi-steps { grid-template-columns: 1fr; }\n      .santi-box { padding: 28px 20px; }\n      .physician-inner { flex-direction: column; text-align: center; }\n    }\n  ";
const html = "\n\n<section class=\"hero\" style=\"background:linear-gradient(118deg, rgba(2,29,40,.9) 0%, rgba(2,45,61,.62) 58%, rgba(2,45,61,.42) 100%), url('/img/hero/lca.jpg') center/cover;\">\n  <div class=\"hero-badge\">Ligamento Cruzado Anterior</div>\n  <h1>Rotura do LCA — Tenho de ser Operado?</h1>\n  <p>A rotura do ligamento cruzado anterior é uma das lesões do joelho mais comuns. A decisão cirúrgica não é automática — depende de si, do seu joelho e do seu estilo de vida.</p>\n  <a href=\"/marcar-consulta\" class=\"hero-cta\">Agendar Consulta</a>\n</section>\n\n<div class=\"quick-facts\">\n  <div class=\"quick-facts-inner\">\n    <div class=\"fact-item\"><strong>~200 000</strong><span>Roturas/ano na Europa</span></div>\n    <div class=\"fact-item\"><strong>70–80%</strong><span>Lesões desportivas</span></div>\n    <div class=\"fact-item\"><strong>9–12 meses</strong><span>Retorno ao desporto</span></div>\n    <div class=\"fact-item\"><strong>90–95%</strong><span>Sucesso da reconstrução</span></div>\n  </div>\n</div>\n\n<div class=\"main\">\n  <div class=\"intro-grid\" style=\"grid-template-columns: 1fr; max-width: 760px;\">\n    <div class=\"intro-text\">\n      <div class=\"section-label\">O que é o LCA</div>\n      <h2 class=\"section-title\">O Ligamento que Estabiliza o Joelho</h2>\n      <p>O ligamento cruzado anterior (LCA) é uma das estruturas mais importantes da estabilidade do joelho. Controla a translação anterior da tíbia em relação ao fémur e resiste à rotação interna — movimentos essenciais em mudanças de direcção, travagens e saltos.</p>\n      <p>A rotura do LCA ocorre tipicamente em mecanismos de desaceleração súbita, pivotagem ou contacto com outro jogador. O doente frequentemente ouve ou sente um \"estalo\", seguido de dor aguda e inchaço rápido do joelho.</p>\n      <p>Cada episódio de instabilidade — a sensação de \"falhar\" do joelho — pode provocar novas lesões dos meniscos e da cartilagem. Por isso, a decisão terapêutica não deve ser adiada indefinidamente.</p>\n      <div class=\"highlight-box\">\n        <p>A rotura do LCA raramente cicatriza espontaneamente. Sem tratamento adequado, o joelho instável acumula lesões secundárias que agravam o prognóstico a longo prazo.</p>\n      </div>\n    </div>\n    \n  </div>\n</div>\n\n<!-- DECISION -->\n<div class=\"decision-section\">\n  <div class=\"decision-inner\">\n    <div class=\"section-label\">Decisão Terapêutica</div>\n    <h2 class=\"section-title\">Cirurgia ou Tratamento Conservador?</h2>\n    <p class=\"section-lead\" style=\"color:#4a5e4a\">Esta é a questão central na rotura do LCA. A resposta não é universal — depende de factores individuais que o especialista avaliará em consulta.</p>\n    <div class=\"decision-grid\">\n      <div class=\"decision-card card-conservative\">\n        <h3>✓ Tratamento Conservador</h3>\n        <ul>\n          <li>Baixo nível de actividade física (sedentário)</li>\n          <li>Joelho estável sem episódios de instabilidade</li>\n          <li>Sem lesões meniscais ou ligamentares associadas</li>\n          <li>Idade avançada com demandas funcionais baixas</li>\n          <li>Recusa do risco cirúrgico / anestésico</li>\n          <li>Fase aguda com AMI grave — pode ser necessário estabilizar primeiro</li>\n        </ul>\n      </div>\n      <div class=\"decision-card card-surgical\">\n        <h3>→ Reconstrução Cirúrgica</h3>\n        <ul>\n          <li>Doente activo com instabilidade recorrente</li>\n          <li>Praticante de desportos com pivotagem (futebol, basquete, ski)</li>\n          <li>Lesões meniscais ou condrais associadas a tratar</li>\n          <li>Falha do tratamento conservador</li>\n          <li>Jovem com elevadas expectativas de retorno ao desporto</li>\n          <li>Lesão combinada multi-ligamentar</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"decision-note\">\n      <strong>Nota clínica:</strong> A investigação actual (revisão sistemática 2024) mostra que o tratamento conservador pode ser adequado para doentes seleccionados — mas o risco de lesões secundárias meniscais e condrais em joelhos instáveis é real e cumulativo. A decisão requer avaliação individualizada.\n    </div>\n  </div>\n</div>\n\n<div class=\"main\">\n  <!-- ENXERTOS -->\n  <div class=\"section-label\">Técnica Cirúrgica</div>\n  <h2 class=\"section-title\">Tipos de Enxerto para Reconstrução do LCA</h2>\n  <p class=\"section-lead\">A reconstrução do LCA utiliza um enxerto de tendão para substituir o ligamento. A escolha do enxerto é individualizada e influencia o resultado a longo prazo.</p>\n  <div class=\"graft-grid\">\n    <div class=\"graft-card\">\n      <div class=\"icon\"></div>\n      <h4>Isquiotibiais (Semitendinoso)</h4>\n      <p>Enxerto mais utilizado. Morbilidade de colheita reduzida, boa resistência mecânica. Pode ser associado ao gracilis para maior volume.</p>\n      <span class=\"graft-tag tag-preferred\">Mais utilizado</span>\n    </div>\n    <div class=\"graft-card\">\n      <div class=\"icon\"></div>\n      <h4>Tendão Rotuliano (BTB)</h4>\n      <p>Enxerto osso-tendão-osso. Integração óssea mais rápida — favorecido em desportos de elite e reconstruções primárias de alta exigência.</p>\n      <span class=\"graft-tag tag-preferred\">Desporto de elite</span>\n    </div>\n    <div class=\"graft-card\">\n      <div class=\"icon\">⬆</div>\n      <h4>Tendão Quadricipital</h4>\n      <p>Crescentemente utilizado. Grande volume de enxerto, morbilidade aceitável, boa integração. Opção válida sobretudo em doentes mais velhos.</p>\n      <span class=\"graft-tag tag-alt\">Tendência crescente</span>\n    </div>\n    <div class=\"graft-card\">\n      <div class=\"icon\"></div>\n      <h4>Enxerto de Banco (Aloenxerto)</h4>\n      <p>Tecido de dador. Sem morbilidade de colheita — reservado para revisões ou situações específicas com escassez de enxerto autólogo.</p>\n      <span class=\"graft-tag tag-revision\">Revisões / casos complexos</span>\n    </div>\n  </div>\n\n  <!-- SANTI PROTOCOL -->\n  <div class=\"santi-box\">\n    <div class=\"section-label\">Protocolo de Excelência</div>\n    <h2>Protocolo SANTI — Tenodese Anterolateral</h2>\n    <p>O protocolo SANTI (desenvolvido pelo Prof. Bertrand Sonnery-Cottet) integra a avaliação e tratamento da inibição artrogénica muscular (AMI) no protocolo cirúrgico do LCA — um diferenciador de resultado que poucos centros aplicam sistematicamente.</p>\n    <div class=\"santi-steps\">\n      <div class=\"santi-step\">\n        <div class=\"num\">01</div>\n        <h4>Avaliação Pré-Operatória da AMI</h4>\n        <p>Classificação da inibição do quadricípite antes da cirurgia. Em casos seleccionados, a cirurgia é adiada até resolução da AMI.</p>\n      </div>\n      <div class=\"santi-step\">\n        <div class=\"num\">02</div>\n        <h4>Cirurgia + Ligamentoplastia Lateral</h4>\n        <p>Reconstrução do LCA associada, quando indicado, à tenodese extra-articular (técnica de Lemaire ou Anterolateral, refinada por Sonnery-Cottet) para controlo da rotação.</p>\n      </div>\n      <div class=\"santi-step\">\n        <div class=\"num\">03</div>\n        <h4>Reabilitação Neuromotora Pós-Op</h4>\n        <p>Protocolo de reactivação do quadricípite e tratamento da AMI residual desde o primeiro dia de pós-operatório.</p>\n      </div>\n    </div>\n  <a href=\"/quadriceps\" style=\"display:inline-block;margin-top:20px;color:var(--sage);font-weight:700;text-decoration:none;border-bottom:2px solid var(--sage);padding-bottom:2px;\">Saber mais sobre a AMI (inibição do quadricípite) →</a></div>\n\n  <!-- RECOVERY TIMELINE -->\n  <div class=\"section-label\">Reabilitação</div>\n  <h2 class=\"section-title\">Marco a Marco — Retorno ao Desporto</h2>\n  <p class=\"section-lead\">O retorno precoce antes dos 9 meses está associado a maior risco de re-rotura. Os critérios de força e funcionais são mais importantes do que o tempo.</p>\n  <div class=\"timeline-grid\">\n    <div class=\"tl-card\"><div class=\"timing\">Dia 1</div><div class=\"milestone\">Marcha com canadianas. Activação do quadricípite.</div></div>\n    <div class=\"tl-card\"><div class=\"timing\">2–4 sem</div><div class=\"milestone\">Marcha sem apoio. Extensão e flexão a 90°.</div></div>\n    <div class=\"tl-card\"><div class=\"timing\">6 sem</div><div class=\"milestone\">Bicicleta ergométrica. Força progressiva.</div></div>\n    <div class=\"tl-card\"><div class=\"timing\">3–4 meses</div><div class=\"milestone\">Corrida em linha recta. Propriocepção avançada.</div></div>\n    <div class=\"tl-card\"><div class=\"timing\">6 meses</div><div class=\"milestone\">Mudanças de direcção. Avaliação de força isocinética.</div></div>\n    <div class=\"tl-card\"><div class=\"timing\">9–12 meses</div><div class=\"milestone\">Retorno ao desporto de contacto após critérios validados.</div></div>\n  </div>\n</div>\n\n<!-- FAQ -->\n<section class=\"faq-section\">\n  <div class=\"section-label\">Perguntas Frequentes</div>\n  <h2 class=\"section-title\" style=\"margin-bottom:32px\">Dúvidas sobre o LCA</h2>\n\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Tenho uma rotura do LCA confirmada na ressonância — tenho de ser operado? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Não necessariamente. A imagem não substitui a avaliação clínica. Doentes com joelhos estáveis e baixa exigência desportiva podem ser tratados de forma conservadora com sucesso. A decisão depende do nível de actividade, da presença de instabilidade e de lesões associadas.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Quanto tempo depois da lesão se deve fazer a cirurgia? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">O timing óptimo depende da presença de inibição artrogénica (AMI) e do derrame articular. Operar com AMI grave ou joelho muito inflamado aumenta o risco de artrofibrose. Em muitos casos, é preferível aguardar 3–6 semanas após a lesão aguda para recuperar amplitude articular e activação muscular antes da cirurgia.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Qual o melhor enxerto para a reconstrução do LCA? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Não existe um enxerto universalmente superior. O tendão rotuliano (BTB) tem integração óssea mais rápida e é frequentemente preferido em desporto de elite. Os isquiotibiais têm menor morbilidade de colheita. O tendão quadricipital ganha crescente popularidade. A escolha deve ser individualizada com o seu cirurgião.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Posso voltar ao futebol após reconstrução do LCA? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Sim — a grande maioria dos doentes regressa ao desporto de nível pré-lesional. O retorno ao futebol de contacto é tipicamente entre os 9 e os 12 meses, condicionado ao cumprimento de critérios de força (&gt;90% simetria quadricípite) e testes funcionais validados. O retorno precoce antes dos 9 meses aumenta significativamente o risco de re-rotura.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">O que é a ligamentoplastia lateral e quando se faz? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">A tenodese extra-articular (técnica de Lemaire ou Anterolateral, refinada por Sonnery-Cottet) é um procedimento adicional à reconstrução do LCA para controlar a rotação interna excessiva do joelho. Hoje em dia as suas indicações abrangem muitos casos clínicos — e não apenas alguns doentes seleccionados: reduzem a taxa de re-rotura do LCA e protegem os meniscos reparados, tendo-se tornado uma das principais \"redescobertas\" da cirurgia do joelho nos últimos anos. Está indicada em doentes com hiperlaxidez, desportos de alta rotação ou história de instabilidade importante. Não é aplicada em todos os casos.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Quanto tempo demora a recuperação completa após reconstrução do LCA? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">A reabilitação é progressiva ao longo de vários meses: marcha e vida diária nas primeiras semanas; corrida por volta dos 3–4 meses; regresso a desportos de pivô/contacto habitualmente entre os 9 e os 12 meses — condicionado por critérios de força, estabilidade e testes funcionais, não apenas pelo tempo.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Posso fazer vida normal com o ligamento cruzado roto? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Para o dia-a-dia, muitas pessoas conseguem, sobretudo após reforço muscular. O problema surge nos movimentos de rotação ou mudança de direção, em que o joelho pode \"falsear\" (instabilidade), aumentando o risco de lesões associadas (menisco, cartilagem). Por isso, em pessoas jovens ou ativas, a reconstrução é geralmente recomendada.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">É possível reduzir o risco de lesão ou re-lesão do LCA? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Sim. Programas de exercícios neuromusculares — reforço muscular, controlo do valgo dinâmico, pliometria e treino de técnica de aterragem e de mudança de direção — reduzem de forma comprovada o risco de lesão do LCA, em particular em atletas. Estes exercícios são também parte essencial da reabilitação, para prevenir a re-lesão após a reconstrução.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Tenho uma rotura parcial do LCA — também precisa de cirurgia? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Depende da estabilidade do joelho, não da percentagem descrita na ressonância. Uma rotura parcial com joelho clinicamente estável — Lachman com paragem firme e pivot-shift negativo — pode ser tratada sem cirurgia, com reabilitação dirigida. Se houver instabilidade ou episódios de falseio, o joelho comporta-se como uma rotura completa e a reconstrução está indicada. O relatório da RM orienta, mas quem decide é o exame clínico.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Tenho rotura do LCA e do menisco ao mesmo tempo — trata-se tudo na mesma cirurgia? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Sim, e há vantagem clara em fazê-lo. Cerca de metade das roturas agudas do LCA tem lesão do <a href=\"/menisco\">menisco</a> associada. A reparação do menisco feita em simultâneo com a reconstrução do ligamento tem melhores taxas de cicatrização — o ambiente biológico criado pela cirurgia do LCA favorece a cicatrização meniscal, e o joelho fica estável, condição sem a qual a sutura do menisco volta a falhar. Adiar a reconstrução aumenta o risco de a lesão meniscal progredir até deixar de ser reparável.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">O que decide o regresso ao desporto — o tempo ou os testes? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Os testes, não o calendário. O tempo é apenas o mínimo biológico necessário para o enxerto integrar — não é prova de que o joelho está pronto. A decisão assenta em critérios objectivos: défice de força do quadricípite inferior a 10% face ao lado são, hop tests simétricos, controlo neuromuscular no gesto desportivo e prontidão psicológica avaliada pela escala ACL-RSI. Segundo dados de Grindem e colaboradores (Br J Sports Med, 2016 — <a href=\"https://doi.org/10.1136/bjsports-2016-096031\" target=\"_blank\" rel=\"noopener\">DOI</a>), até aos 9 meses cada mês adicional antes do regresso reduz o risco de re-lesão em cerca de 51% — e passar nos critérios protege mais do que esperar por uma data no calendário.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Quando posso voltar a correr? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Habitualmente entre os 3 e os 4 meses, mas por critérios e não por calendário. Antes de correr, o joelho deve ter extensão completa, ausência de derrame e força do <a href=\"/quadriceps\">quadricípite</a> acima de 80% do lado contralateral. Correr com défice de quadricípite instala padrões de compensação que atrasam todo o resto da recuperação — é uma das razões mais frequentes para uma reabilitação estagnar aos 5 ou 6 meses.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Quando posso voltar a conduzir? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Se foi operado ao joelho direito, conte com 4 a 6 semanas: é o tempo em que a reacção à travagem de emergência regressa a valores normais. Com o joelho esquerdo operado e caixa automática pode regressar mais cedo, por volta das 2 semanas, desde que consiga entrar e sair do carro sem apoio e sem dor. Nunca conduza sob analgesia opióide. Confirme também as condições da sua apólice de seguro automóvel.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Quanto tempo de baixa médica vou precisar? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Depende da exigência física do trabalho, não da cirurgia em si. Trabalho sedentário: habitualmente 3 a 4 semanas, e menos se houver possibilidade de teletrabalho. Trabalho que exige estar de pé, deslocações frequentes ou condução: 8 a 12 semanas. Trabalho físico pesado, escadas ou trabalho em altura: 4 a 6 meses. A baixa é emitida no pós-operatório e prolongada em consulta conforme a evolução.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">A cirurgia é em ambulatório? Que anestesia se usa? Vou ter muitas dores? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Na maioria dos casos a reconstrução do LCA faz-se em ambulatório ou com uma noite de internamento. A anestesia é habitualmente locorregional — bloqueio do canal dos adutores, preferido ao bloqueio femoral por poupar a força do quadricípite — associada a sedação ou anestesia geral. A dor mais intensa concentra-se nas primeiras 48 a 72 horas e é controlável com medicação oral, gelo e elevação. Sai a andar com canadianas no próprio dia.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">E se o enxerto voltar a romper? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">É tratável, com reconstrução de revisão. Segundo uma meta-análise publicada no American Journal of Sports Medicine, a taxa global de segunda lesão do LCA após reconstrução ronda os 15% — cerca de 7% no joelho operado e 8% no joelho contralateral — subindo para cerca de 23% em atletas com menos de 25 anos que regressam ao desporto. A revisão exige planeamento próprio: avaliar a posição e o alargamento dos túneis, o alinhamento do membro, o slope tibial e as lesões meniscais e ligamentares associadas. Pode ser feita num só tempo ou em dois, e o reforço anterolateral está indicado na quase totalidade das revisões.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">O meu filho adolescente rompeu o LCA — pode ser operado antes de acabar de crescer? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Sim, e em regra não se deve adiar. Esperar pelo fim do crescimento com um joelho instável aumenta significativamente o risco de lesões do menisco e da cartilagem, que são irreversíveis. Existem técnicas de reconstrução que respeitam as fises de crescimento, escolhidas em função da maturidade esquelética e não da idade cronológica. Neste grupo o risco de re-lesão é o mais elevado de todos, pelo que o programa de reabilitação e os critérios de regresso ao desporto têm de ser cumpridos com rigor.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Posso operar o LCA pelo SNS com vale cirurgia? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Sim. Se estiver inscrito em lista de espera para cirurgia num hospital do SNS e o tempo de espera ultrapassar 75% do tempo máximo de resposta garantido, é emitido um <a href=\"/sigic\">vale cirurgia (SIGIC)</a> que lhe permite ser operado num hospital convencionado à sua escolha, sem custos para si. Todas as unidades onde opero aceitam vale cirurgia para a reconstrução do LCA.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">Quando posso voltar ao desporto? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">Hoje em dia, nove meses para os desportos de pivô e de contacto. O enxerto não é um ligamento no dia da cirurgia: passa por um processo de remodelação biológica — a ligamentização — que o converte progressivamente em tecido semelhante ao ligamento nativo, e que aos seis meses ainda está longe de completo. Isto não significa parar até lá: muito antes disso retomam-se o ginásio, a bicicleta estática, a pliometria e actividades como o yoga. O que fica reservado para os nove meses é a rotação e o pivô — submeter um enxerto biologicamente imaturo a cargas de corte e de rotação é o que aumenta o risco. Aos nove meses, cumpridos os critérios de força e de controlo neuromuscular, a margem de segurança é substancialmente maior.</div>\n  </div>\n  <div class=\"faq-item\">\n    <button class=\"faq-q\" onclick=\"toggleFaq(this)\">E se o enxerto voltar a romper? A revisão dá bom resultado? <span class=\"arrow\">▾</span></button>\n    <div class=\"faq-a\">A revisão do LCA dá bons resultados: a grande maioria dos doentes recupera a estabilidade do joelho e regressa à sua actividade. É honesto dizer, ainda assim, que os resultados são em média ligeiramente inferiores aos de uma primeira cirurgia — no registo nacional sueco, com mais de 20.000 doentes, a melhoria foi menor em todas as subescalas do KOOS após revisão, com a maior diferença no domínio do desporto. A taxa de falência situa-se entre 8% e 13%, contra cerca de 4% na cirurgia primária, e em cerca de um quarto dos casos encontra-se uma lesão da cartilagem que não existia na primeira intervenção. Nada disto desaconselha a revisão — significa que vale a pena fazer bem a primeira.</div>\n  </div>\n<div class=\"faq-item\"><button class=\"faq-q\" onclick=\"toggleFaq(this)\">Quanto custa a cirurgia ao ligamento cruzado? <span class=\"arrow\">▾</span></button><div class=\"faq-a\">Como doente particular, a reconstrução do LCA começa nos €3.000. Este valor inclui habitualmente a estadia em ambulatório, o material de consumo básico do bloco operatório e o material necessário à realização da ligamentoplastia. Não inclui o material específico para tratar lesões associadas — como a <a href=\"/menisco\">reparação do menisco</a> ou o tratamento de lesões da cartilagem —, que, a existirem, acrescem ao valor. O custo final depende ainda do tipo de implantes e do regime de internamento. Com seguro de saúde, a maior parte é comparticipada mediante pré-autorização prévia; e se estiver inscrito em lista de espera do SNS acima do tempo garantido, pode ser operado sem qualquer custo através de <a href=\"/sigic\">vale cirurgia (SIGIC)</a>.</div></div></section>\n\n<div class=\"physician-strip\">\n  <div class=\"physician-inner\">\n    <div class=\"physician-avatar\">NC</div>\n    <div class=\"physician-info\">\n      <h4>Dr. Nuno Camelo Barbosa</h4>\n      <p>Cirurgião Ortopédico · Subespecialista de Joelho<br>Hospital Lusíadas Porto · Hospital Misericórdia Vila do Conde · Paços de Ferreira</p>\n      <div class=\"credentials\"><span class=\"cred-tag\">LCA</span><span class=\"cred-tag\">Extra-articular</span><span class=\"cred-tag\">Estabilidade ligamentar</span></div>\n    </div>\n  </div>\n</div>\n\n<section class=\"cta-section\">\n  <h2>Teve uma lesão do LCA?</h2>\n  <p>A decisão entre cirurgia e tratamento conservador requer uma avaliação especializada presencial. Marque a sua consulta no Porto, Paços de Ferreira ou Vila do Conde.</p>\n  <a href=\"/marcar-consulta\" class=\"btn-primary\">Agendar Consulta</a>\n  <a href=\"tel:+351926850194\" class=\"btn-secondary\">926 850 194</a>\n</section>\n\n\n\n\n<section class=\"references\" style=\"max-width:900px;margin:2.5rem auto 0;padding:1.3rem 1.5rem;border:1px solid var(--border,#e2ece1);border-radius:14px;font-family:'Space Grotesk',sans-serif;\"><h2 style=\"font-size:1rem;font-weight:700;color:var(--teal,#035772);margin:0 0 .3rem;\">Referências</h2><p style=\"font-size:.8rem;color:var(--muted,#6b7280);margin:0 0 .8rem;\">Guidelines de sociedades científicas e revisões que sustentam esta informação.</p><ol style=\"margin:0;padding-left:1.2rem;font-size:.85rem;color:var(--text,#091405);line-height:1.5;\"><li style=\"margin-bottom:.5rem;\"><a href=\"https://www.aaos.org/aaos-home/newsroom/press-releases/aaos-updates-guideline-for-management-of-acl-injuries/\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--teal,#035772);text-decoration:none;\">AAOS Clinical Practice Guideline — Management of Anterior Cruciate Ligament Injuries. American Academy of Orthopaedic Surgeons, 2022.</a></li><li style=\"margin-bottom:.5rem;\"><a href=\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10598192/\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--teal,#035772);text-decoration:none;\">Management of ACL revision: the 2022 ESSKA consensus. Knee Surg Sports Traumatol Arthrosc, 2023.</a></li><li style=\"margin-bottom:.5rem;\"><a href=\"https://pubmed.ncbi.nlm.nih.gov/41209365/\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--teal,#035772);text-decoration:none;\">Watson SL, et al. ACL Injury Risk Reduction: Demonstration of Key Exercises. Video Journal of Sports Medicine, 2025. PMID 41209365.</a></li><li style=\"margin-bottom:.5rem;\"><a href=\"https://pubmed.ncbi.nlm.nih.gov/35478294/\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--teal,#035772);text-decoration:none;\">Remnant preservation may improve proprioception after anterior cruciate ligament reconstruction. Journal of Orthopaedics and Traumatology, 2022. PMID 35478294.</a></li></ol></section><div class=\"author-box\" style=\"max-width:900px;margin:2.75rem auto 0;padding:1.4rem 1.5rem;border:1px solid var(--border,#e2ece1);border-radius:14px;background:var(--bg,#f6f9f5);display:flex;gap:1.25rem;align-items:center;flex-wrap:wrap;font-family:'Space Grotesk',sans-serif;\"><img src=\"/img/dr-nuno-camelo.jpg\" alt=\"Dr. Nuno Camelo Barbosa\" width=\"86\" height=\"86\" loading=\"lazy\" style=\"width:86px;height:86px;border-radius:50%;object-fit:cover;object-position:center 30%;flex-shrink:0;\"><div style=\"flex:1;min-width:230px;\"><div style=\"font-weight:700;color:var(--teal,#035772);font-size:1.05rem;\">Dr. Nuno Camelo Barbosa</div><div style=\"color:var(--text,#091405);font-size:.9rem;margin-top:.15rem;\">Cirurgião ortopédico · Subespecialista em cirurgia do joelho</div><div style=\"color:var(--muted,#6b7280);font-size:.82rem;margin-top:.3rem;\">Revisor científico (AJSM · KSSTA · OJSM · JEO)</div><div style=\"color:var(--muted,#6b7280);font-size:.8rem;margin-top:.5rem;\">Última revisão médica: <strong style=\"color:var(--teal,#035772);font-weight:600;\">24 de julho de 2026</strong></div><div style=\"margin-top:.7rem;font-size:.85rem;\"><a href=\"/nuno-camelo-especialista-cirurgia-joelho\" style=\"color:var(--teal,#035772);font-weight:600;text-decoration:none;\">Ver perfil completo</a> &nbsp;·&nbsp; <a href=\"/marcar-consulta\" style=\"color:var(--teal,#035772);font-weight:600;text-decoration:none;\">Marcar consulta →</a></div></div></div>";
const jsonLd = "{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"MedicalWebPage\",\"name\":\"Rotura do Ligamento Cruzado Anterior (LCA)\",\"description\":\"Guia clínico sobre rotura do LCA: diagnóstico, decisão terapêutica e reabilitação\",\"url\":\"https://www.consultajoelho.pt/ligamentocruzadoanterior\",\"author\":{\"@type\":\"Physician\",\"name\":\"Dr. Nuno Camelo Barbosa\",\"medicalSpecialty\":\"Orthopaedic Surgery\"},\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Tenho uma rotura do LCA — tenho de ser operado?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não necessariamente. A decisão depende do nível de actividade, idade, presença de instabilidade e lesões associadas. Doentes sedentários com joelho estável podem ser tratados de forma conservadora. Doentes activos com instabilidade repetida têm indicação cirúrgica.\"}},{\"@type\":\"Question\",\"name\":\"Quanto tempo dura a recuperação da cirurgia ao LCA?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"A maioria dos doentes regressa ao desporto entre 9 e 12 meses após a cirurgia, quando cumprem critérios de força e funcionais validados. O retorno precoce antes dos 9 meses está associado a maior risco de re-rotura.\"}}],\"dateModified\":\"2026-07-24\",\"lastReviewed\":\"2026-07-24\",\"reviewedBy\":{\"@type\":\"Physician\",\"name\":\"Dr. Nuno Camelo Barbosa\",\"url\":\"https://www.consultajoelho.pt/nuno-camelo-especialista-cirurgia-joelho\",\"medicalSpecialty\":\"Orthopedic\",\"sameAs\":[\"https://orcid.org/0000-0002-7443-4085\",\"https://www.researchgate.net/profile/Nuno-Camelo-Barbosa\",\"https://scholar.google.com/citations?user=iTCpAfYAAAAJ\",\"https://linkedin.com/in/nuno-camelo-barbosa-07b37277\"]},\"citation\":[\"https://www.aaos.org/aaos-home/newsroom/press-releases/aaos-updates-guideline-for-management-of-acl-injuries/\",\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10598192/\",\"https://pubmed.ncbi.nlm.nih.gov/41209365/\",\"https://pubmed.ncbi.nlm.nih.gov/35478294/\"],\"about\":{\"@type\":\"MedicalCondition\",\"name\":\"Rotura do ligamento cruzado anterior\"}},{\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Tenho uma rotura do LCA confirmada na ressonância — tenho de ser operado?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não necessariamente. A imagem não substitui a avaliação clínica. Doentes com joelhos estáveis e baixa exigência desportiva podem ser tratados de forma conservadora com sucesso. A decisão depende do nível de actividade, da presença de instabilidade e de lesões associadas.\"}},{\"@type\":\"Question\",\"name\":\"Quanto tempo depois da lesão se deve fazer a cirurgia?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"O timing óptimo depende da presença de inibição artrogénica (AMI) e do derrame articular. Operar com AMI grave ou joelho muito inflamado aumenta o risco de artrofibrose. Em muitos casos, é preferível aguardar 3–6 semanas após a lesão aguda para recuperar amplitude articular e activação muscular antes da cirurgia.\"}},{\"@type\":\"Question\",\"name\":\"Qual o melhor enxerto para a reconstrução do LCA?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Não existe um enxerto universalmente superior. O tendão rotuliano (BTB) tem integração óssea mais rápida e é frequentemente preferido em desporto de elite. Os isquiotibiais têm menor morbilidade de colheita. O tendão quadricipital ganha crescente popularidade. A escolha deve ser individualizada com o seu cirurgião.\"}},{\"@type\":\"Question\",\"name\":\"Posso voltar ao futebol após reconstrução do LCA?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim — a grande maioria dos doentes regressa ao desporto de nível pré-lesional. O retorno ao futebol de contacto é tipicamente entre os 9 e os 12 meses, condicionado ao cumprimento de critérios de força (>90% simetria quadricípite) e testes funcionais validados. O retorno precoce antes dos 9 meses aumenta significativamente o risco de re-rotura.\"}},{\"@type\":\"Question\",\"name\":\"O que é a ligamentoplastia lateral e quando se faz?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"A tenodese extra-articular (técnica de Lemaire ou Anterolateral, refinada por Sonnery-Cottet) é um procedimento adicional à reconstrução do LCA para controlar a rotação interna excessiva do joelho. Hoje em dia as suas indicações abrangem muitos casos clínicos — e não apenas alguns doentes seleccionados: reduzem a taxa de re-rotura do LCA e protegem os meniscos reparados, tendo-se tornado uma das principais \\\"redescobertas\\\" da cirurgia do joelho nos últimos anos. Está indicada em doentes com hiperlaxidez, desportos de alta rotação ou história de instabilidade importante. Não é aplicada em todos os casos.\"}},{\"@type\":\"Question\",\"name\":\"Quanto tempo demora a recuperação completa após reconstrução do LCA?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"A reabilitação é progressiva ao longo de vários meses: marcha e vida diária nas primeiras semanas; corrida por volta dos 3–4 meses; regresso a desportos de pivô/contacto habitualmente entre os 9 e os 12 meses — condicionado por critérios de força, estabilidade e testes funcionais, não apenas pelo tempo.\"}},{\"@type\":\"Question\",\"name\":\"Posso fazer vida normal com o ligamento cruzado roto?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Para o dia-a-dia, muitas pessoas conseguem, sobretudo após reforço muscular. O problema surge nos movimentos de rotação ou mudança de direção, em que o joelho pode \\\"falsear\\\" (instabilidade), aumentando o risco de lesões associadas (menisco, cartilagem). Por isso, em pessoas jovens ou ativas, a reconstrução é geralmente recomendada.\"}},{\"@type\":\"Question\",\"name\":\"É possível reduzir o risco de lesão ou re-lesão do LCA?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim. Programas de exercícios neuromusculares — reforço muscular, controlo do valgo dinâmico, pliometria e treino de técnica de aterragem e de mudança de direção — reduzem de forma comprovada o risco de lesão do LCA, em particular em atletas. Estes exercícios são também parte essencial da reabilitação, para prevenir a re-lesão após a reconstrução.\"}},{\"@type\":\"Question\",\"name\":\"Tenho uma rotura parcial do LCA — também precisa de cirurgia?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Depende da estabilidade do joelho, não da percentagem descrita na ressonância. Uma rotura parcial com joelho clinicamente estável — Lachman com paragem firme e pivot-shift negativo — pode ser tratada sem cirurgia, com reabilitação dirigida. Se houver instabilidade ou episódios de falseio, o joelho comporta-se como uma rotura completa e a reconstrução está indicada. O relatório da RM orienta, mas quem decide é o exame clínico.\"}},{\"@type\":\"Question\",\"name\":\"Tenho rotura do LCA e do menisco ao mesmo tempo — trata-se tudo na mesma cirurgia?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim, e há vantagem clara em fazê-lo. Cerca de metade das roturas agudas do LCA tem lesão do menisco associada. A reparação do menisco feita em simultâneo com a reconstrução do ligamento tem melhores taxas de cicatrização — o ambiente biológico criado pela cirurgia do LCA favorece a cicatrização meniscal, e o joelho fica estável, condição sem a qual a sutura do menisco volta a falhar. Adiar a reconstrução aumenta o risco de a lesão meniscal progredir até deixar de ser reparável.\"}},{\"@type\":\"Question\",\"name\":\"O que decide o regresso ao desporto — o tempo ou os testes?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Os testes, não o calendário. O tempo é apenas o mínimo biológico necessário para o enxerto integrar — não é prova de que o joelho está pronto. A decisão assenta em critérios objectivos: défice de força do quadricípite inferior a 10% face ao lado são, hop tests simétricos, controlo neuromuscular no gesto desportivo e prontidão psicológica avaliada pela escala ACL-RSI. Segundo dados de Grindem e colaboradores (Br J Sports Med, 2016 — DOI), até aos 9 meses cada mês adicional antes do regresso reduz o risco de re-lesão em cerca de 51% — e passar nos critérios protege mais do que esperar por uma data no calendário.\"}},{\"@type\":\"Question\",\"name\":\"Quando posso voltar a correr?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Habitualmente entre os 3 e os 4 meses, mas por critérios e não por calendário. Antes de correr, o joelho deve ter extensão completa, ausência de derrame e força do quadricípite acima de 80% do lado contralateral. Correr com défice de quadricípite instala padrões de compensação que atrasam todo o resto da recuperação — é uma das razões mais frequentes para uma reabilitação estagnar aos 5 ou 6 meses.\"}},{\"@type\":\"Question\",\"name\":\"Quando posso voltar a conduzir?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Se foi operado ao joelho direito, conte com 4 a 6 semanas: é o tempo em que a reacção à travagem de emergência regressa a valores normais. Com o joelho esquerdo operado e caixa automática pode regressar mais cedo, por volta das 2 semanas, desde que consiga entrar e sair do carro sem apoio e sem dor. Nunca conduza sob analgesia opióide. Confirme também as condições da sua apólice de seguro automóvel.\"}},{\"@type\":\"Question\",\"name\":\"Quanto tempo de baixa médica vou precisar?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Depende da exigência física do trabalho, não da cirurgia em si. Trabalho sedentário: habitualmente 3 a 4 semanas, e menos se houver possibilidade de teletrabalho. Trabalho que exige estar de pé, deslocações frequentes ou condução: 8 a 12 semanas. Trabalho físico pesado, escadas ou trabalho em altura: 4 a 6 meses. A baixa é emitida no pós-operatório e prolongada em consulta conforme a evolução.\"}},{\"@type\":\"Question\",\"name\":\"A cirurgia é em ambulatório? Que anestesia se usa? Vou ter muitas dores?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Na maioria dos casos a reconstrução do LCA faz-se em ambulatório ou com uma noite de internamento. A anestesia é habitualmente locorregional — bloqueio do canal dos adutores, preferido ao bloqueio femoral por poupar a força do quadricípite — associada a sedação ou anestesia geral. A dor mais intensa concentra-se nas primeiras 48 a 72 horas e é controlável com medicação oral, gelo e elevação. Sai a andar com canadianas no próprio dia.\"}},{\"@type\":\"Question\",\"name\":\"E se o enxerto voltar a romper?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"É tratável, com reconstrução de revisão. Segundo uma meta-análise publicada no American Journal of Sports Medicine, a taxa global de segunda lesão do LCA após reconstrução ronda os 15% — cerca de 7% no joelho operado e 8% no joelho contralateral — subindo para cerca de 23% em atletas com menos de 25 anos que regressam ao desporto. A revisão exige planeamento próprio: avaliar a posição e o alargamento dos túneis, o alinhamento do membro, o slope tibial e as lesões meniscais e ligamentares associadas. Pode ser feita num só tempo ou em dois, e o reforço anterolateral está indicado na quase totalidade das revisões.\"}},{\"@type\":\"Question\",\"name\":\"O meu filho adolescente rompeu o LCA — pode ser operado antes de acabar de crescer?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim, e em regra não se deve adiar. Esperar pelo fim do crescimento com um joelho instável aumenta significativamente o risco de lesões do menisco e da cartilagem, que são irreversíveis. Existem técnicas de reconstrução que respeitam as fises de crescimento, escolhidas em função da maturidade esquelética e não da idade cronológica. Neste grupo o risco de re-lesão é o mais elevado de todos, pelo que o programa de reabilitação e os critérios de regresso ao desporto têm de ser cumpridos com rigor.\"}},{\"@type\":\"Question\",\"name\":\"Posso operar o LCA pelo SNS com vale cirurgia?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Sim. Se estiver inscrito em lista de espera para cirurgia num hospital do SNS e o tempo de espera ultrapassar 75% do tempo máximo de resposta garantido, é emitido um vale cirurgia (SIGIC) que lhe permite ser operado num hospital convencionado à sua escolha, sem custos para si. Todas as unidades onde opero aceitam vale cirurgia para a reconstrução do LCA.\"}},{\"@type\":\"Question\",\"name\":\"Quando posso voltar ao desporto?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Hoje em dia, nove meses para os desportos de pivô e de contacto. O enxerto não é um ligamento no dia da cirurgia: passa por um processo de remodelação biológica — a ligamentização — que o converte progressivamente em tecido semelhante ao ligamento nativo, e que aos seis meses ainda está longe de completo. Isto não significa parar até lá: muito antes disso retomam-se o ginásio, a bicicleta estática, a pliometria e actividades como o yoga. O que fica reservado para os nove meses é a rotação e o pivô — submeter um enxerto biologicamente imaturo a cargas de corte e de rotação é o que aumenta o risco. Aos nove meses, cumpridos os critérios de força e de controlo neuromuscular, a margem de segurança é substancialmente maior.\"}},{\"@type\":\"Question\",\"name\":\"E se o enxerto voltar a romper? A revisão dá bom resultado?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"A revisão do LCA dá bons resultados: a grande maioria dos doentes recupera a estabilidade do joelho e regressa à sua actividade. É honesto dizer, ainda assim, que os resultados são em média ligeiramente inferiores aos de uma primeira cirurgia — no registo nacional sueco, com mais de 20.000 doentes, a melhoria foi menor em todas as subescalas do KOOS após revisão, com a maior diferença no domínio do desporto. A taxa de falência situa-se entre 8% e 13%, contra cerca de 4% na cirurgia primária, e em cerca de um quarto dos casos encontra-se uma lesão da cartilagem que não existia na primeira intervenção. Nada disto desaconselha a revisão — significa que vale a pena fazer bem a primeira.\"}},{\"@type\":\"Question\",\"name\":\"Quanto custa a cirurgia ao ligamento cruzado?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Como doente particular, a reconstrução do LCA começa nos €3.000. Este valor inclui habitualmente a estadia em ambulatório, o material de consumo básico do bloco operatório e o material necessário à realização da ligamentoplastia. Não inclui o material específico para tratar lesões associadas — como a reparação do menisco ou o tratamento de lesões da cartilagem —, que, a existirem, acrescem ao valor. O custo final depende ainda do tipo de implantes e do regime de internamento. Com seguro de saúde, a maior parte é comparticipada mediante pré-autorização prévia; e se estiver inscrito em lista de espera do SNS acima do tempo garantido, pode ser operado sem qualquer custo através de vale cirurgia (SIGIC).\"}}]},{\"@type\":\"BreadcrumbList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"name\":\"Início\",\"item\":\"https://www.consultajoelho.pt\"},{\"@type\":\"ListItem\",\"position\":2,\"name\":\"Rotura do LCA — Cirurgia ou Tratamento Conservador?\",\"item\":\"https://www.consultajoelho.pt/lca\"}]}]}";
